// DaemonServer is the server API for Daemon service.
// All implementations must embed UnimplementedDaemonServer
// for forward compatibility.
type DaemonServer interface {
	// Health is the gRPC twin of /readyz.
	Health(context.Context, *HealthRequest) (*HealthResponse, error)
	// Initialize hands the daemon its instance configuration after boot. Idempotent: a restored or restarted
	// daemon returns `already_initialized` and keeps its workspace, applying only lease and endpoint changes.
	Initialize(context.Context, *InitializeRequest) (*InitializeResponse, error)
	// GetInfo returns the daemon version, agent catalog and live connections.
	GetInfo(context.Context, *GetInfoRequest) (*DaemonInfo, error)
	// ProbeAgents runs the section 4.2a probe (`initialize` + `session/new` in a scratch dir, no prompt) for the
	// golden template build.
	ProbeAgents(context.Context, *ProbeAgentsRequest) (*ProbeAgentsResponse, error)
	// PrepareSuspend settles every in-flight entity and, for snapshots, clears token files, tmpfs credentials and
	// cloud SDK caches (and stops subscription-backed Codex processes for shared snapshots). The gateway calls it
	// before SuspendActor and before snapshots, after reading the event stream up to `settled_offset`.
	PrepareSuspend(context.Context, *PrepareSuspendRequest) (*PrepareSuspendResponse, error)
	// SubscribeEvents streams the event log from an offset, then follows it live. The gateway holds exactly one
	// subscription per running instance, and closes it before suspending.
	SubscribeEvents(*SubscribeEventsRequest, grpc.ServerStreamingServer[DaemonEvent]) error
	// AckEvents acknowledges that everything up to an offset reached console; the daemon may trim its log.
	AckEvents(context.Context, *AckEventsRequest) (*AckEventsResponse, error)
	// GetTimeline pages a session's transcript: settled entities from the workspace volume merged with in-flight
	// ones, plus the event log head the page reflects.
	GetTimeline(context.Context, *GetTimelineRequest) (*GetTimelineResponse, error)
	// GetSessions returns every thread and subagent row and the live agent connections.
	GetSessions(context.Context, *GetSessionsRequest) (*GetSessionsResponse, error)
	CreateThread(context.Context, *CreateThreadRequest) (*ThreadResponse, error)
	ListThreads(context.Context, *ListThreadsRequest) (*ListThreadsResponse, error)
	ImportThread(context.Context, *ImportThreadRequest) (*ThreadResponse, error)
	ResumeThread(context.Context, *ResumeThreadRequest) (*ThreadResponse, error)
	CloseThread(context.Context, *ThreadActionRequest) (*ThreadResponse, error)
	DeleteThread(context.Context, *ThreadActionRequest) (*DeleteThreadResponse, error)
	ForkThread(context.Context, *ForkThreadRequest) (*ThreadResponse, error)
	Prompt(context.Context, *PromptRequest) (*PromptResponse, error)
	CancelPrompt(context.Context, *CancelPromptRequest) (*CancelPromptResponse, error)
	SetThreadConfigOption(context.Context, *SetThreadConfigOptionRequest) (*SetThreadConfigOptionResponse, error)
	RespondInteraction(context.Context, *RespondInteractionRequest) (*RespondInteractionResponse, error)
	ListCommands(context.Context, *ListCommandsRequest) (*ListCommandsResponse, error)
	SetAgentBilling(context.Context, *SetAgentBillingRequest) (*SetAgentBillingResponse, error)
	CreateTerminal(context.Context, *CreateTerminalRequest) (*TerminalInfo, error)
	ListTerminals(context.Context, *ListTerminalsRequest) (*ListTerminalsResponse, error)
	ResizeTerminal(context.Context, *ResizeTerminalRequest) (*TerminalInfo, error)
	CloseTerminal(context.Context, *CloseTerminalRequest) (*TerminalInfo, error)
	// AttachTerminal is the gRPC form of /terminals/<id>/ws (used by the CLI path). First frame: `attach`.
	AttachTerminal(grpc.BidiStreamingServer[TerminalInput, TerminalOutput]) error
	ListFiles(context.Context, *ListFilesRequest) (*ListFilesResponse, error)
	StatFile(context.Context, *StatFileRequest) (*StatFileResponse, error)
	ReadFile(context.Context, *ReadFileRequest) (*ReadFileResponse, error)
	WriteFile(context.Context, *WriteFileRequest) (*WriteFileResponse, error)
	WatchFiles(*WatchFilesRequest, grpc.ServerStreamingServer[FileEvent]) error
	GetChanges(context.Context, *GetChangesRequest) (*GetChangesResponse, error)
	// AddRepository clones through egress into ~/<repo> and registers it in Project.md's managed table.
	AddRepository(context.Context, *AddRepositoryRequest) (*AddRepositoryResponse, error)
	ListRepositories(context.Context, *ListRepositoriesRequest) (*ListRepositoriesResponse, error)
	StartBrowser(context.Context, *StartBrowserRequest) (*BrowserInfo, error)
	StopBrowser(context.Context, *StopBrowserRequest) (*BrowserInfo, error)
	GetBrowser(context.Context, *GetBrowserRequest) (*BrowserInfo, error)
	// SetLeases relays Control.SetInstanceLeases.
	SetLeases(context.Context, *SetInstanceLeasesRequest) (*SetInstanceLeasesResponse, error)
	GetIdleState(context.Context, *GetIdleStateRequest) (*IdleState, error)
	// PushCredential installs a Codex bundle refreshed elsewhere (fan-out from the lease holder) or a changed
	// refresh lease. Only kind CODEX is accepted.
	PushCredential(context.Context, *PushCredentialRequest) (*PushCredentialResponse, error)
	mustEmbedUnimplementedDaemonServer()
}

